def seed_to_state(seed):
    """
    A simple utility function to safely return the correct state
    from `STATE_DICT` given a correct seed

    We avoid using `STATE_DICT.get(seed)` to ensure that we raise
    an IndexError if the `seed` isn't found
    """
    return STATE_DICT[seed]
